$ErrorActionPreference='Stop';$root=$PSScriptRoot;Import-Module (Join-Path $root 'Repato.AgentOrchestration.psm1') -Force;Import-Module (Join-Path $root 'Repato.Deployment.v4.psm1') -Force;Import-Module (Join-Path $root 'Repato.MayaQaWorkflow.psm1') -Force;. (Join-Path $root 'MayaQa.TaraExecution.ps1')
function New-Case {
 $root2=Join-Path ([IO.Path]::GetTempPath()) ('neil-matrix-'+[guid]::NewGuid().ToString('N'));$store=Join-Path $root2 'store';$target=Join-Path $root2 'target';New-Item $target -ItemType Directory -Force|Out-Null;$id='matrix-'+[guid]::NewGuid().ToString('N').Substring(0,12);New-RepatoTask $store $id 'matrix' 'build evidence' 'qa/test'|Out-Null;Claim-RepatoTask $store $id 'Neil'|Out-Null;Update-RepatoTask $store $id 'in-progress' 'implementation' 'Neil' $null $null|Out-Null;Update-RepatoTask $store $id 'in-progress' 'build-checks' 'Neil' $null $null|Out-Null;$a=Join-Path $target 'Repato.Revit.dll';$m=Join-Path $target 'runner.addin';Set-Content $a ('synthetic artifact '+$id);Set-Content $m ('synthetic manifest '+$id);$plan=New-DeployPlan $store $id $a $m -TargetRoot $target;$w=New-DeployWorkflow $store $plan;$fixture='C:\Repato-Autonomous\Source\QA\Fixtures\CreatePlanViewsEmpty.rvt';$run=Join-Path $target 'run';New-Item $run -ItemType Directory|Out-Null;$model=Join-Path $run 'model.rvt';Copy-Item $fixture $model;$sidecar=$model+'.fixture.json';$fh=(Get-FileHash $fixture).Hash;@{fixtureId='CreatePlanViewsEmpty';sourceSha256=$fh}|ConvertTo-Json|Set-Content $sidecar;$bid='build-'+[guid]::NewGuid().ToString('N');$wid=$w.workflowId;$rid='run-'+[guid]::NewGuid().ToString('N').Substring(0,8);$hid='handoff-'+[guid]::NewGuid().ToString('N');$native='create-plan-views-v1';$d=Read-RepatoTaskStore $store;$t=Find-RepatoTask $d $id;$w=@(Invoke-RepatoWorkflowMutation $store $id $wid $w.workflowRevision $t.revision {param($x)$x|Add-Member NoteProperty qaBuildRequest ([pscustomobject]@{BuildRequestId=$bid}) -Force;$x|Add-Member NoteProperty qaBuildStatus 'succeeded' -Force;$x|Add-Member NoteProperty qaBuildEvidence ([pscustomobject]@{BuildRequestId=$bid;BuildStatus='succeeded';ExitCode=0;Configuration='Release';ArtifactPath=$a;ArtifactSha256=(Get-FileHash $a).Hash;ManifestPath=$m;ManifestSha256=(Get-FileHash $m).Hash}) -Force;return $x})[-1].Workflow;Update-RepatoTask $store $id 'passed' 'qa' 'Tara' $null $null|Out-Null;$null=Request-RepatoTaskApproval $store $id 'qa-run' 'maya';Resolve-RepatoTaskApproval $store $id approve 'Maya' 'synthetic approval'|Out-Null;$approval=@((Find-RepatoTask (Read-RepatoTaskStore $store) $id).approvalRequests|Where-Object {$_.action -ceq 'qa-run' -and $_.status -ceq 'approved'})[-1];$d=Read-RepatoTaskStore $store;$t=Find-RepatoTask $d $id;$w=@(Invoke-RepatoWorkflowMutation $store $id $wid $w.workflowRevision $t.revision {param($x)$x|Add-Member NoteProperty qaHandoffId $hid -Force;$x|Add-Member NoteProperty qaHandoff ([pscustomobject]@{HandoffId=$hid;HandoffStatus='ready';TaskId=$id;QaWorkflowId='create-plan-views-v1';BuildRequestId=$bid;FixtureId='CreatePlanViewsEmpty';NativeTestId=$native;ModelPath=$model;SidecarPath=$sidecar;ArtifactPath=$a;ArtifactSha256=(Get-FileHash $a).Hash;ManifestPath=$m;ManifestSha256=(Get-FileHash $m).Hash}) -Force;$x|Add-Member NoteProperty qaApprovalId $approval.requestId -Force;$x|Add-Member NoteProperty qaApprovalStatus 'approved' -Force;$x|Add-Member NoteProperty qaRunId $rid -Force;$x|Add-Member NoteProperty qaWorkflowId 'create-plan-views-v1' -Force;$x|Add-Member NoteProperty qaModelPath $model -Force;$x|Add-Member NoteProperty qaSidecarPath $sidecar -Force;$x|Add-Member NoteProperty qaFixtureId 'CreatePlanViewsEmpty' -Force;$x|Add-Member NoteProperty qaFixtureSha256 $fh -Force;$x|Add-Member NoteProperty qaTestId $native -Force;return $x})[-1].Workflow;[pscustomobject]@{Root=$root2;Store=$store;Target=$target;TaskId=$id;WorkflowId=$wid;RunId=$rid;QaId='create-plan-views-v1';Model=$model;Sidecar=$sidecar;Artifact=$a;Manifest=$m;BuildId=$bid;HandoffId=$hid;ApprovalId=$approval.requestId;Workflow=$w}
}
$cases=@(
 @{Name='01_missing_qaBuildEvidence';Mutate={param($w)$w.PSObject.Properties.Remove('qaBuildEvidence')}},
 @{Name='02_qaBuildStatus_not_succeeded';Mutate={param($w)$w.qaBuildStatus='failed'}},
 @{Name='03_BuildStatus_not_succeeded';Mutate={param($w)$w.qaBuildEvidence.BuildStatus='failed'}},
 @{Name='04_ExitCode_nonzero';Mutate={param($w)$w.qaBuildEvidence.ExitCode=1}},
 @{Name='05_Configuration_not_Release';Mutate={param($w)$w.qaBuildEvidence.Configuration='Debug'}},
 @{Name='06_missing_BuildRequestId';Mutate={param($w)$w.qaBuildEvidence.PSObject.Properties.Remove('BuildRequestId')}},
 @{Name='07_qaBuildRequest_BuildRequestId_mismatch';Mutate={param($w)$w.qaBuildRequest.BuildRequestId='wrong'}},
 @{Name='08_buildEvidence_BuildRequestId_mismatch';Mutate={param($w)$w.qaBuildEvidence.BuildRequestId='wrong'}},
 @{Name='09_missing_ArtifactPath';Mutate={param($w)$w.qaBuildEvidence.ArtifactPath=$null}},
 @{Name='10_artifact_hash_mismatch';Mutate={param($w)$w.qaBuildEvidence.ArtifactSha256=('0'*64)}},
 @{Name='11_missing_ManifestPath';Mutate={param($w)$w.qaBuildEvidence.ManifestPath=$null}},
 @{Name='12_manifest_hash_mismatch';Mutate={param($w)$w.qaBuildEvidence.ManifestSha256=('0'*64)}}
)
$results=@();foreach($c in $cases){$x=New-Case;$d=Read-RepatoTaskStore $x.Store;$t=Find-RepatoTask $d $x.TaskId;$w=Get-DeployWorkflow $x.Store $x.TaskId $x.WorkflowId;@($null=Invoke-RepatoWorkflowMutation $x.Store $x.TaskId $x.WorkflowId $w.workflowRevision $t.revision {param($z)&$c.Mutate $z;return $z})|Out-Null;$err=$null;$rejected=$false;try{Invoke-MayaQaTaraExecute -StoreRoot $x.Store -TaskId $x.TaskId -WorkflowId $x.WorkflowId -QaWorkflowId $x.QaId -RunId $x.RunId -ReportDirectory $x.Target -QaAddinRoot $x.Target -DryRun|Out-Null}catch{$rejected=$true;$err=$_.Exception.Message};$results+=[pscustomobject]@{Case=$c.Name;Rejected=$rejected;Error=$err;SideEffects=$false};Remove-Item $x.Root -Recurse -Force};$results|Format-Table -AutoSize;if(@($results|Where-Object{-not $_.Rejected}).Count){throw 'One or more invalid Neil evidence cases were accepted.'};"Invalid Neil evidence matrix passed: $($results.Count)/12"
